CREATE TABLE IF NOT EXISTS portals (
    id INT AUTO_INCREMENT PRIMARY KEY,
    service_name VARCHAR(255),
    service_category VARCHAR(100),
    sub_category VARCHAR(100),
    official_website VARCHAR(255),
    description TEXT,
    government_fee VARCHAR(100),
    recommended_service_charge VARCHAR(100),
    eligibility TEXT,
    application_process TEXT,
    required_documents TEXT,
    authorization_required VARCHAR(100),
    csc_required BOOLEAN,
    grama_one_required BOOLEAN,
    aadhaar_operator_required BOOLEAN,
    last_verified_date DATE,
    portal_status VARCHAR(50)
);


CREATE TABLE IF NOT EXISTS portal_registry (
    id VARCHAR(50) PRIMARY KEY,
    portal_name VARCHAR(255) NOT NULL,
    category VARCHAR(100) NOT NULL,
    official_url VARCHAR(255) NOT NULL,
    notification_url VARCHAR(255) NOT NULL,
    rss_url VARCHAR(255),
    last_checked TIMESTAMP,
    active BOOLEAN DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS portal_updates (
    id VARCHAR(50) PRIMARY KEY,
    portal_name VARCHAR(255) NOT NULL,
    title VARCHAR(255) NOT NULL,
    summary TEXT,
    source_url VARCHAR(255) NOT NULL,
    published_date DATE NOT NULL,
    priority VARCHAR(50) NOT NULL,
    category VARCHAR(100) NOT NULL,
    detected_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

